-- Histori transaksi SAP 2026 bulan 1–9 untuk item master (dari SAP Inventory Posting List, data s/d 2026-09-04).
-- Jalankan SETELAH schema.sql (atau 002_transactions.sql) dan seed.sql. Mengganti histori item-item ini pada rentang bulan tsb.
begin;
delete from public.transactions t using public.items i where t.item_id = i.id and t.year = 2026 and t.month between 1 and 9 and i.code in ('12002','12003','12006','12007','12008','12009','12011','12012','12013','12014','12016','12020','12021','12026','12028','12029','12030','12031','15001','15006','15007','15008','15014','15017','15022','15024','15025','15038','15041','15043','15044','15045','15046','15047','15048','15049','15053','15054','15055');
commit;
